-- Run once (seed_runs). Kerala Tier A leaders, generated by scraper/src/bihar/leaders-cli.ts from the curated
-- scraper/data/kl/leaders.json and leader-profiles.json: candidacy links (never moving curated or merged
-- persons), fill-only profile fields, and the leaders/cabinet watchlists of each Kerala manifest (written once;
-- admins edit them afterwards). Persons and image credits above the guard are idempotent and run every time.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_kl_leaders')
   AS seed_apply \gset
\if :seed_apply

-- Link each leader's candidacies to the best-linked person. A candidacy moves from a one-candidacy person or from a
-- person whose candidacies all belong to this leader (leaders.json is curated); never from a merge, a split or a
-- person with an admin-entered profile.

-- Profiles, fill-only (admin edits win)
UPDATE persons SET photo_url = COALESCE(photo_url, 'https://matdaanpulse-media.s3.ap-south-1.amazonaws.com/persons/Q6956446/photo.jpg'), date_of_birth = COALESCE(date_of_birth, '1964-05-31'::date), gender = COALESCE(gender, 'M'), wikipedia_url = COALESCE(wikipedia_url, 'https://en.wikipedia.org/wiki/V._D._Satheesan'), bio = COALESCE(bio, 'Chief Minister of Kerala in the 2026 government.'), state_id = COALESCE(state_id, 16) WHERE id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('309676f1-eea8-5a19-a26e-da8e6c50c046') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1);
