WHERE id = 'a7b8c9d0-e1f2-3456-0123-678901232026' AND manifest_url LIKE '{%' AND CASE WHEN manifest_url LIKE '{%' THEN NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(manifest_url::jsonb->'watchlists', '[]'::jsonb)) w WHERE jsonb_array_length(COALESCE(w->'entries', '[]'::jsonb)) > 0) ELSE false END;
